var LADDERS=[{"id": "neg", "name": "Negative numbers", "why": "Negative numbers appear in temperatures, money you owe, and the depth of a dive. Being confident with them makes algebra and graphs much easier later, and mistakes with signs are one of the most common ways to lose marks.", "help": ["A number line is your friend: moving right adds, moving left subtracts.", "Adding a negative is the same as subtracting. Subtracting a negative is the same as adding.", "When you multiply or divide: same signs give a positive, different signs give a negative."], "tool": "numberline", "levels": [{"n": 1, "name": "Simple subtraction", "desc": "5 − 12", "tip": "Count back past zero."}, {"n": 2, "name": "Adding to a negative number", "desc": "−7 + 9", "tip": "Start below zero and move up."}, {"n": 3, "name": "Adding and subtracting", "desc": "−10 − 2", "tip": "Turn double signs into one sign."}, {"n": 4, "name": "Multiplying", "desc": "−3 × 2", "tip": "Same signs give positive, different signs negative."}, {"n": 5, "name": "Dividing", "desc": "−10 ÷ 5", "tip": "Divide the numbers, then decide the sign."}, {"n": 6, "name": "Substitution", "desc": "If a = −3, work out 4a + 1", "tip": "Use brackets when you replace a letter with a negative number."}, {"n": 7, "name": "Word problems", "desc": "Temperatures, money and lifts", "tip": "Write the calculation before you work it out."}], "about": "Add, subtract, multiply and divide with numbers below zero, and use them in real situations.", "words": [{"w": "negative number", "d": "A number below zero, written with a minus sign, like −5."}, {"w": "operation", "d": "Adding, subtracting, multiplying or dividing."}, {"w": "substitute", "d": "Replace a letter with a number."}]}, {"id": "frac", "name": "Fractions", "why": "Fractions are how we describe parts of things: pizza slices, discounts, probabilities and shares of money. Getting comfortable with them now saves a lot of stress with ratio, percentages and algebra.", "help": ["Equivalent fractions: do the same to the top and the bottom.", "To simplify, divide the top and bottom by the same number, as many times as you can.", "To add fractions the bottom numbers must match. Change one fraction first if they do not."], "tool": null, "levels": [{"n": 1, "name": "Equivalent fractions", "desc": "2/3 = ?/6", "tip": "What was the bottom multiplied by?"}, {"n": 2, "name": "Simplifying", "desc": "Write 6/8 in its simplest form", "tip": "Keep dividing until nothing else goes into both."}, {"n": 3, "name": "Same denominators", "desc": "2/7 + 3/7", "tip": "Keep the bottom number, add the tops."}, {"n": 4, "name": "Fractions of an amount", "desc": "3/4 of 20", "tip": "Divide by the bottom, multiply by the top."}, {"n": 5, "name": "Different denominators", "desc": "1/2 + 1/4", "tip": "Make the bottoms match first."}, {"n": 6, "name": "Word problems", "desc": "Pizza slices and pocket money", "tip": "Decide what the whole is."}], "about": "Find equivalent fractions, simplify, add fractions and find fractions of amounts.", "words": [{"w": "numerator", "d": "The top number of a fraction."}, {"w": "denominator", "d": "The bottom number of a fraction."}, {"w": "equivalent", "d": "Equal in value, like 1/2 and 2/4."}, {"w": "simplest form", "d": "A fraction where nothing else divides into both the top and bottom."}]}, {"id": "pct", "name": "Percentages", "why": "Percent means out of 100. You will use it for sale prices, test scores, phone battery levels and interest on savings, so it is one of the most useful skills in maths.", "help": ["10% is one tenth. Divide by 10, then build up: 20% is two lots of 10%.", "50% is a half and 25% is a quarter.", "To turn a percentage into a decimal, divide by 100."], "tool": null, "levels": [{"n": 1, "name": "10% and 50%", "desc": "10% of 60", "tip": "Divide by 10 for 10%, by 2 for 50%."}, {"n": 2, "name": "25%, 75% and 1%", "desc": "25% of 80", "tip": "Find a quarter, or divide by 100 for 1%."}, {"n": 3, "name": "Percentages and decimals", "desc": "Write 35% as a decimal", "tip": "Percent means out of 100."}, {"n": 4, "name": "Finding a percentage", "desc": "30% of 90", "tip": "Find 10% first, then scale up."}, {"n": 5, "name": "Word problems", "desc": "Sale prices and price rises", "tip": "Work out the change, then add or subtract it."}], "about": "Find percentages of amounts and move between percentages and decimals.", "words": [{"w": "percent", "d": "Out of 100."}, {"w": "increase", "d": "Make bigger: add on the change."}, {"w": "reduction", "d": "Make smaller: take away the change."}]}, {"id": "alg", "name": "Algebra", "why": "Algebra lets us write rules that work for any number. It is the language behind spreadsheets, coding, science formulae and puzzles, so it is worth building a strong start.", "help": ["A letter stands for a number. 4n means 4 × n.", "To solve an equation, do the opposite operation to both sides.", "With two-step equations, undo the adding or subtracting first, then undo the multiplying."], "tool": null, "levels": [{"n": 1, "name": "Substitution", "desc": "Work out 3n when n = 5", "tip": "Replace the letter with the number."}, {"n": 2, "name": "Collecting like terms", "desc": "4x + 3x", "tip": "Add or subtract the numbers in front of x."}, {"n": 3, "name": "One-step equations", "desc": "n + 5 = 12", "tip": "Do the opposite."}, {"n": 4, "name": "Two-step equations", "desc": "3x + 2 = 14", "tip": "Undo the adding first, then the multiplying."}, {"n": 5, "name": "Number machines and rules", "desc": "Multiply by 3, then subtract 2", "tip": "Follow the steps in order."}, {"n": 6, "name": "Word problems", "desc": "Taxis and ages", "tip": "Write what you know as a calculation."}], "about": "Substitute into expressions, collect terms, solve equations and use algebra in word problems.", "words": [{"w": "expression", "d": "Numbers and letters together, like 3n + 2."}, {"w": "term", "d": "One part of an expression, like 3n."}, {"w": "equation", "d": "Two expressions with an equals sign, like 3x + 2 = 14."}, {"w": "opposite operation", "d": "The operation that undoes another: subtracting undoes adding."}]}];
